// TH14 v1.00b st04bs2.ecl.txt::BossBCard1 (source lines 326-375) + BossBCard1_at (377-466).
// Source t0 = card122; emission source t90 fires first at card214 (emit task start offset 2).
const TIME_LIMIT: int = 3024;
const SOURCE_LIMIT: int = 2400;
const OPENING_BUFFER: int = 120;

// Source etEx records 1-6 of BossBCard1_at: three 40-frame ANGLE_ACCEL (speed +0.016/+0.015/-0.02
// per frame, angular velocity A/B/C), then 200 frames at angular velocity D, then record6 GOTO
// index5 -> 200-frame chunks at -D forever. ANGLE_ACCEL = per-frame angle += s, speed += r.
// Record0 ANIM (a=1) is the omitted birth stage; its 4*speed retreat is folded into sh_dist.
xformdef NOTE_SPIN(a: angle, b: angle, c: angle, d: angle) {
    set_ang_vel(a);
    set_accel(0.016fx);
    wait(40);
    set_ang_vel(b);
    set_accel(0.015fx);
    wait(40);
    set_ang_vel(c);
    set_accel(-0.02fx);
    wait(40);
    set_ang_vel(d);
    set_accel(0fx);
    wait(200);
spin:
    set_ang_vel(0bam - d);
    wait(200);
    goto spin;
}

// moveRand(60,4,0.4) recipe from transcribe/th16/movement.md, limit (0,128,280,64):
// actual position x[-140,140] y[96,160]; direction inner box x+-70 y112..144.
// int0 = next movement step; fx0/fx1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.4fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 412: signed unit random * pi, one sampling per call; central branch adds a WORD%3.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel_xy(0, 0fx, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
sub card_stop() {
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
}

// Source RANDF2: uniform [-1, 1).
sub rand_signed() {
    // Values stay in enemy slots because ordinary subs have no return value.
    set_self_fx(2, ((rand(65536)-32768) as fx)/32768);
}

sub emit_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { return; }
    }
}

// st04bs2.ecl.txt::BossBCard1_at, spawned at source t90.
async sub emit() {
    sh_reset(0);
    sh_sprite(0, TH14_NOTE_BLUE, 0);
    sh_aim(0, 1);
    sh_ring(0, 0);
    sh_speed(0, 0.4fx, 0fx);
    sh_dist(0, 30.4fx); // source etDist 32 minus ANIM a=1 retreat 4*0.4
    var rank: int = global(GVAR_RANK);
    var ways: int = 3;
    var spread: angle = 60deg;
    var interval: int = 12;
    if rank == 1 { ways = 6; spread = 30deg; }
    if rank == 2 { ways = 8; spread = 20deg; }
    if rank == 3 { ways = 12; spread = 17deg; interval = 10; }
    sh_count(0, ways, 1);
    // Source 380-383: A..D start at 0.008*RANDF2 (rad/frame angular velocity).
    rand_signed();
    var a: fx = 0.008fx*self_fx(2);
    rand_signed();
    var b: fx = 0.008fx*self_fx(2);
    rand_signed();
    var c: fx = 0.008fx*self_fx(2);
    rand_signed();
    var d: fx = 0.008fx*self_fx(2);
    var left: int = 1200; // source $E
    loop {
        if $frame >= self_int(1) { return; }
        if left <= 0 { return; }
        left = left-1;
        // Source etAngle: ANGLE_PLAYER + 0.06981317*RANDF2 (+-4deg = +-728 BAM).
        sh_angle(0, (rand(1456)-728) as angle, spread);
        sh_xform(0, NOTE_SPIN(
            ((a*10430.378fx) as int) as angle,
            ((b*10430.378fx) as int) as angle,
            ((c*10430.378fx) as int) as angle,
            ((d*10430.378fx) as int) as angle));
        sh_fire(0);
        // Source 420-450: one random-walk step per wave, clamped to +-0.01 rad.
        rand_signed();
        a = a+0.004fx*self_fx(2);
        if a < -0.01fx { a = -0.01fx; } else if a > 0.01fx { a = 0.01fx; }
        rand_signed();
        b = b+0.004fx*self_fx(2);
        if b < -0.01fx { b = -0.01fx; } else if b > 0.01fx { b = 0.01fx; }
        rand_signed();
        c = c+0.004fx*self_fx(2);
        if c < -0.01fx { c = -0.01fx; } else if c > 0.01fx { c = 0.01fx; }
        rand_signed();
        d = d+0.008fx*self_fx(2);
        if d < -0.01fx { d = -0.01fx; } else if d > 0.01fx { d = 0.01fx; }
        emit_wait(interval);
    }
}

// st04bs2.ecl.txt::BossBCard1 main: entry clears, 60-frame move to (0,144), limit, then the
// wait(60)/wait(80|20)/moveRand/wait(70) cycle whose source clock resets to 90 each iteration.
async sub pattern() {
    wait(OPENING_BUFFER);
    set_self_int(2, $frame);
    set_self_int(1, $frame+SOURCE_LIMIT);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    set_self_fx(2, 0fx);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);
    wait(30); // source t60..90: anmSelect only
    spawn emit();
    var settle: int = 80;
    if global(GVAR_RANK) == 3 { settle = 20; }
    loop {
        card_wait(60);
        if $frame >= self_int(1) { card_stop(); return; }
        card_wait(settle);
        if $frame >= self_int(1) { card_stop(); return; }
        card_move_rand();
        card_wait(70);
        if $frame >= self_int(1) { card_stop(); return; }
    }
}

// Entry shell: BossB公共入口 state (0,128), hurt/hit box 48/48 -> r=24, spell 52, timer 2400.
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    spell_begin(0, 52, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    card_stop();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_main);
    loop { wait(600); }
}

